-- Read-only aggregate reconciliation. No member contact details returned.
with cats as (select id,name from communication_category where tenant_id='ff2df806-b321-4254-b651-3af11fccf1db' and id in ('814e0ba4-5afe-4e84-a502-81002ae34a93','683b3d0f-3136-4cc8-bb39-b50c9496d1e8')), m as (select * from member where tenant_id='ff2df806-b321-4254-b651-3af11fccf1db'), p as (select p.* from member_communication_preference p join cats c on c.id=p.category_id where p.tenant_id='ff2df806-b321-4254-b651-3af11fccf1db'), states as (select m.id,c.id category_id,c.name,case when coalesce(m.email,'')='' then 'missing_email' when m.email ~* '^deleted_.*@deleted[.]local$' then 'deleted_email' when m.login_enabled=false then 'disabled_login' when m.communications_opted_out_all=true then 'global_opt_out' else 'eligible' end eligibility, case when exists(select 1 from p where p.member_id=m.id and p.category_id=c.id and is_subscribed=true) then 'true' when exists(select 1 from p where p.member_id=m.id and p.category_id=c.id and is_subscribed=false) then 'false' when exists(select 1 from p where p.member_id=m.id and p.category_id=c.id) then 'null' else 'missing' end preference from m cross join cats c), matrix as (select id,eligibility,max(preference) filter(where category_id='683b3d0f-3136-4cc8-bb39-b50c9496d1e8') newsletter,max(preference) filter(where category_id='814e0ba4-5afe-4e84-a502-81002ae34a93') announcements from states group by id,eligibility) select jsonb_build_object('observed_at',now(),'tenant_members',(select count(*) from m),'counts',(select jsonb_agg(x) from (select name,eligibility,preference,count(*) n from states group by 1,2,3 order by 1,2,3)x),'matrix',(select jsonb_agg(x) from(select eligibility,newsletter,announcements,count(*) n from matrix group by 1,2,3 order by 1,2,3)x),'preference_quality',(select jsonb_agg(x) from(select c.name,count(p.id) rows,count(p.id) filter(where m.id is null) orphan_or_foreign_rows,count(p.id)-count(distinct p.member_id) duplicate_excess from cats c left join p on p.category_id=c.id left join m on m.id=p.member_id group by c.name)x),'external',(select jsonb_agg(x) from(select c.name,e.opted_out,count(e.id) n from cats c left join email_subscriber e on e.communication_category_id=c.id and e.tenant_id='ff2df806-b321-4254-b651-3af11fccf1db' group by c.name,e.opted_out)x),'overlapping_exclusions',(select jsonb_agg(x) from(select coalesce(email,'')='' missing_email,coalesce(email ~* '^deleted_.*@deleted[.]local$',false) deleted_email,login_enabled is false disabled_login,communications_opted_out_all is true global_opt_out,count(*) n from m group by 1,2,3,4)x)) evidence;
